'use strict';
/* ============================================================
   APEX — an ode to Formula 1. Application.
   Everything below reads from DATA; nothing writes to it.
   ============================================================ */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const D=DATA.drivers, T=DATA.teams, S=DATA.seasons, ERAS=DATA.eras, CIRC=DATA.circuits, LAY=DATA.layouts;
const RM=matchMedia('(prefers-reduced-motion: reduce)').matches;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number.isInteger(n)?String(n):(Math.round(n*100)/100).toString();
const pct=(a,b)=>b?Math.round(a/b*1000)/10:0;
const name=id=>D[id]?.name||id, short=id=>D[id]?.short||id, code=id=>D[id]?.code||String(id).slice(0,3).toUpperCase();
const tn=id=>T[id]?.name||id;
/* Teams the source leaves on its placeholder lavender get a deterministic muted hue of their own, so the 1950s are not one purple blur. Presentation only: DATA is untouched. */
const hueCache={};const hsl2hex=(h,s,l)=>{s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));return '#'+[f(0),f(8),f(4)].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('');};
const color=id=>{const c=T[id]?.color;if(c&&c.toLowerCase()!=='#b5a5ed')return c;if(hueCache[id])return hueCache[id];let h=0;for(const ch of String(id))h=(h*31+ch.charCodeAt(0))>>>0;return hueCache[id]=hsl2hex(h%360,38,58);};
const finished=x=>x.status==='Finished'||/^\+\d+ Lap/.test(x.status);
const lapSeconds=t=>{if(!t)return null;let v=t.replace(/^\+/,'').split(':').map(Number);if(v.some(n=>!Number.isFinite(n)))return null;return v.reduce((a,n)=>a*60+n,0);};
const fmtLap=s=>{if(s==null)return '—';let m=Math.floor(s/60),r=s-m*60;return (m?m+':':'')+(m?r.toFixed(3).padStart(6,'0'):r.toFixed(3));};
const byYear=Object.fromEntries(S.map(s=>[s.year,s]));
const eraOf=y=>ERAS.find(e=>y>=e.from&&y<=e.to);
const lum=hex=>{let m=/^#?([0-9a-f]{6})$/i.exec(hex||'');if(!m)return .5;let n=parseInt(m[1],16),r=(n>>16)/255,g=(n>>8&255)/255,b=(n&255)/255;const f=c=>c<=.03928?c/12.92:((c+.055)/1.055)**2.4;return .2126*f(r)+.7152*f(g)+.0722*f(b);};
const onColor=hex=>lum(hex)>.42?'#07080a':'#f4f4f2';
const teamVar=id=>`--team:${color(id)}`;
const mixHex=(a,b,t)=>{const p=h=>{const m=/^#?([0-9a-f]{6})$/i.exec(h);if(!m)return [128,128,128];const n=parseInt(m[1],16);return [n>>16,n>>8&255,n&255];};const x=p(a),y=p(b);return '#'+x.map((v,i)=>Math.round(v*t+y[i]*(1-t)).toString(16).padStart(2,'0')).join('');};

/* ---------- state ---------- */
const state={era:'all',year:S[S.length-1].year,tab:'season',race:1,driver:null,team:null,circuit:null,lens:'wins',heat:'wins',heatBy:'d',duelBy:'d',dA:null,dB:null,gridSort:'count',gridFind:'',focusTeam:null,whole:false};
const eraSeasons=()=>S.filter(s=>state.era==='all'||(s.year>=ERAS.find(e=>e.id===state.era).from&&s.year<=ERAS.find(e=>e.id===state.era).to));
const eraRaces=()=>eraSeasons().flatMap(s=>s.races.filter(r=>r.rows.length).map(r=>({...r,year:s.year})));
const eraLabel=()=>state.era==='all'?'All eras · 1950–2026':(e=>`${e.name} · ${e.from}–${e.to}`)(ERAS.find(e=>e.id===state.era));

/* ---------- standings, ordered (the source lists 1952 and 1953 without a published table) ---------- */
const stCache={};const isNum=p=>/^\d+$/.test(String(p));
function standingsOf(s){if(stCache[s.year])return stCache[s.year];let dr,derived=false;if(s.drivers.some(x=>isNum(x.p))){dr=[...s.drivers].sort((a,b)=>(isNum(a.p)?+a.p:1e9)-(isNum(b.p)?+b.p:1e9)||b.pts-a.pts);}else{derived=true;const m={};for(const r of s.races){for(const x of r.rows.concat(r.sprint)){let a=m[x.d]||(m[x.d]={id:x.d,pts:0,wins:0,teams:[]});a.pts+=x.pts;if(!a.teams.includes(x.t))a.teams.push(x.t);}for(const x of r.rows)if(x.dw&&m[x.d])m[x.d].wins++;}dr=Object.values(m).sort((a,b)=>b.pts-a.pts||b.wins-a.wins).map((x,i)=>({...x,p:String(i+1)}));}return stCache[s.year]={drivers:dr,derived};}

/* ---------- circuit outlines (decoded once, drawn many times) ---------- */
const pathCache={};
function pathD(layoutId){if(pathCache[layoutId]!==undefined)return pathCache[layoutId];let l=LAY[layoutId];if(!l||!l.asset){pathCache[layoutId]='';return '';}try{let svg=atob(l.asset.slice(l.asset.indexOf(',')+1));let m=/ d="([^"]+)"/.exec(svg);pathCache[layoutId]=m?m[1]:'';}catch(e){pathCache[layoutId]='';}return pathCache[layoutId];}
function outline(layoutId,opts={}){let d=pathD(layoutId);if(!d)return `<svg viewBox="0 0 500 500" aria-hidden="true"><circle cx="250" cy="250" r="160" fill="none" stroke="#2a2f39" stroke-width="20"/></svg>`;let lap=opts.lap?`<path class="lap" d="${d}" style="--d:${opts.delay||0}s"/>`:'';return `<svg viewBox="0 0 500 500" aria-hidden="true" preserveAspectRatio="xMidYMid meet"><path class="base" d="${d}"/><path class="glow" d="${d}"/><path class="line" d="${d}"/>${lap}</svg>`;}
function latestLayout(cid){let best=null;for(const s of S)for(const r of s.races)if(r.cid===cid&&r.layout)best=r.layout;return best||CIRC[cid]?.layouts?.slice(-1)[0];}

/* ---------- aggregates (same semantics as the prototype) ---------- */
function aggregates(rr,by='d'){const map={};const k=by==='d'?'d':'c';for(const r of rr){for(const x of r.rows){let a=map[x[by]]||(map[x[by]]={id:x[by],wins:0,podiums:0,gp:0,sprint:0,entries:0,fl:0,grid1:0,nf:0,teams:new Set(),drivers:new Set(),races:new Set(),seasons:new Set(),first:r.year,last:r.year});a.entries+=x[k+'e'];a.races.add(r.year+'-'+r.round);a.seasons.add(r.year);a.gp+=x.pts;a.wins+=x[k+'w'];a.podiums+=x[k+'p'];a.fl+=x[k+'f'];a.grid1+=x[k+'g'];a.nf+=x[k+'n'];a.teams.add(x.t);a.drivers.add(x.d);a.first=Math.min(a.first,r.year);a.last=Math.max(a.last,r.year);}for(const x of r.sprint){if(map[x[by]])map[x[by]].sprint+=x.pts;}}return Object.values(map);}
function enriched(rr,by){return aggregates(rr,by).map(a=>{const den=by==='d'?a.entries:a.races.size;return {...a,total:a.gp+a.sprint,winRate:pct(a.wins,den),podiumRate:pct(a.podiums,a.entries),finishRate:pct(a.entries-a.nf,a.entries)};});}
const LENSES={wins:['GP wins','Total Grand Prix victories. Sprints excluded.'],podiums:['GP podiums','Top-three Grand Prix classifications. Sprints excluded.'],fl:['Fastest laps','Rank-1 race laps, whether or not a bonus point was awarded.'],grid1:['Grid P1','First on the GP starting grid; not necessarily the official pole statistic.'],gp:['GP points','Awarded Grand Prix points, including applicable fastest-lap bonuses.'],sprint:['Sprint points','Awarded sprint points, shown separately from Grand Prix results.'],winRate:['Win rate %','GP wins divided by Grands Prix entered. Constructor denominator is race weekends, not car entries.'],podiumRate:['Podium rate %','Podium finishes divided by GP entries. Constructor denominator is individual car entries.'],finishRate:['Finish-status rate %','Finished or +N Lap(s), divided by GP entries. Other statuses include retirements, disqualifications and non-starts.']};
const HEATMETRICS={...LENSES,champPoints:['Championship points','Published season standings, including championship penalties and adjustments.'],entries:['GP car entries','Driver result entries or constructor car entries, including non-starts and non-qualifications.'],nf:['Non-finish statuses','Retirements, disqualifications and non-starts; higher values indicate more non-finish statuses.']};

/* ---------- theme ---------- */
function champTeam(season){let d=standingsOf(season).drivers[0];return d?.teams?.[0]||season.teams?.[0]?.id||null;}
function applyTheme(){let sel=$('#theme'),v=sel.value,root=document.documentElement,acc,sec,ter,ink;if(v==='champion'){let t=state.whole?(enriched(eraRaces(),'t').sort((a,b)=>b.total-a.total)[0]?.id):champTeam(byYear[state.year]);acc=t?color(t):'#FF8000';sec='#1D1D1B';ter='#8b9099';ink=onColor(acc);sel.options[0].textContent=`Champion’s colours · ${t?tn(t):'—'}`;}else{let o=sel.selectedOptions[0];acc=v;sec=o.dataset.secondary;ter=o.dataset.tertiary;ink=o.dataset.ink;}root.style.setProperty('--accent',acc);root.style.setProperty('--accent2',sec);root.style.setProperty('--accent3',ter);root.style.setProperty('--on-accent',ink);}

/* ---------- lights out ---------- */
function lightsOut(){const box=$('#lights'),row=$('#lightRow');let seen=false;try{seen=sessionStorage.getItem('apex-lights')==='1';}catch(e){}
  const out=()=>{box.classList.add('out');setTimeout(()=>box.remove(),800);try{sessionStorage.setItem('apex-lights','1');}catch(e){}};
  if(seen||RM){box.remove();return;}
  row.innerHTML=Array.from({length:5},()=>`<div class="col"><span class="bulb"></span><span class="bulb"></span><span class="bulb live"></span><span class="bulb live"></span></div>`).join('');
  const cols=$$('#lightRow .col');let i=0;const step=()=>{if(!box.isConnected)return;if(i<5){cols[i++].classList.add('on');setTimeout(step,640);}else setTimeout(()=>{cols.forEach(c=>c.classList.remove('on'));setTimeout(out,180);},700+Math.random()*1400);};
  setTimeout(step,500);$('#skipLights').addEventListener('click',out);document.addEventListener('keydown',e=>{if(box.isConnected&&(e.key==='Enter'||e.key==='Escape'||e.key===' '))out();},{once:true});}

/* ---------- the River ---------- */
function smooth(pts){if(pts.length<3)return pts.map((p,i)=>(i?'L':'')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join('');let d='';for(let i=0;i<pts.length-1;i++){const p0=pts[i-1]||pts[i],p1=pts[i],p2=pts[i+1],p3=pts[i+2]||p2;const c1=[p1[0]+(p2[0]-p0[0])/6,p1[1]+(p2[1]-p0[1])/6],c2=[p2[0]-(p3[0]-p1[0])/6,p2[1]-(p3[1]-p1[1])/6];d+=`C${c1[0].toFixed(1)} ${c1[1].toFixed(1)} ${c2[0].toFixed(1)} ${c2[1].toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`;}return d;}
let riverModel=null;const ERA_SHORT={front:'Front-engine',mid:'Mid-engine',wings:'Wings',turbo:'Ground effect · turbo',electronic:'Electronics',v10:'V10',v8:'V8',hybrid:'Hybrid',ground:'GE return',active:'Active'};
function buildRiver(){
  const years=S.map(s=>s.year),shares=[],totals=[],champs=[];const teamFirst={},teamTotal={};
  for(const s of S){const pts={};let tot=0;for(const r of s.races){for(const x of r.rows){pts[x.t]=(pts[x.t]||0)+x.pts;tot+=x.pts;}for(const x of r.sprint){pts[x.t]=(pts[x.t]||0)+x.pts;tot+=x.pts;}}
    for(const t in pts){if(teamFirst[t]===undefined)teamFirst[t]=s.year;teamTotal[t]=(teamTotal[t]||0)+pts[t];}
    shares.push(pts);totals.push(tot);champs.push({d:standingsOf(s).drivers[0]?.id,t:champTeam(s),races:s.races.filter(r=>r.rows.length).length});}
  const teams=Object.keys(teamFirst).sort((a,b)=>teamFirst[a]-teamFirst[b]||teamTotal[b]-teamTotal[a]);
  riverModel={years,shares,totals,champs,teams,teamTotal};
}
function drawRiver(){
  if(!riverModel)buildRiver();const {years,shares,totals,champs,teams,teamTotal}=riverModel;
  const svg=$('#riverSvg'),box=svg.getBoundingClientRect(),W=Math.max(320,box.width),H=Math.max(200,box.height);
  svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
  /* With an era lens on, the river zooms: only that era's seasons are drawn and they take the full width. */
  const era=state.era==='all'?null:ERAS.find(e=>e.id===state.era);
  const i0=era?years.indexOf(era.from):0,i1=era?years.indexOf(era.to):years.length-1,n=i1-i0+1;
  const padL=8,padR=era?64:56,top=40,bottom=26,plotH=H-top-bottom;
  const slotW=n===1?(W-padL-padR)*.42:(W-padL-padR)/(n-1);
  const x=i=>n===1?padL+(W-padL-padR)/2:padL+(i-i0)*slotW;
  const maxRaces=Math.max(...champs.slice(i0,i1+1).map(c=>c.races));
  const thick=i=>plotH*(era?0.45+0.55*champs[i].races/maxRaces:0.28+0.72*champs[i].races/maxRaces);
  const y0=i=>top+(plotH-thick(i))/2;
  const cum=years.map(()=>0);let bands='';const eraTotal={};
  for(let i=i0;i<=i1;i++)for(const t in shares[i])eraTotal[t]=(eraTotal[t]||0)+shares[i][t];
  const drawTeams=era?teams.filter(t=>eraTotal[t]>0):teams;
  for(const t of drawTeams){const up=[],down=[];let any=false;
    for(let i=i0;i<=i1;i++){const sh=totals[i]?(shares[i][t]||0)/totals[i]:0;const a=y0(i)+cum[i]*thick(i);const b=a+sh*thick(i);cum[i]+=sh;up.push([x(i),a]);down.push([x(i),b]);if(sh>0)any=true;}
    if(!any)continue;
    if(n===1){const w=slotW/2;up.unshift([up[0][0]-w,up[0][1]]);up.push([up[1][0]+w,up[1][1]]);down.unshift([down[0][0]-w,down[0][1]]);down.push([down[1][0]+w,down[1][1]]);}
    const dn=down.reverse();const d='M'+up[0][0].toFixed(1)+' '+up[0][1].toFixed(1)+smooth(up)+'L'+dn[0][0].toFixed(1)+' '+dn[0][1].toFixed(1)+smooth(dn)+'Z';
    const tot=era?eraTotal[t]:teamTotal[t];bands+=`<path class="band${state.focusTeam===t?' focus':''}" data-t="${esc(t)}" d="${d}" fill="${color(t)}" stroke="#07080a" stroke-width=".5"><title>${esc(tn(t))} · ${fmt(Math.round(tot))} points ${era?'in this era':'since '+years[shares.findIndex(s=>s[t])]}</title></path>`;}
  let eras='';
  if(era){eras=`<text class="era-label" x="${padL}" y="${top-14}" style="fill:var(--accent)">${esc(era.name)} · ${era.from}–${era.to} · ${drawTeams.length} constructors scored</text>`;}
  else for(const e of ERAS){const k=years.indexOf(e.from);if(k<0)continue;const xx=x(k);const nxt=ERAS[ERAS.indexOf(e)+1];const slot=(nxt&&years.indexOf(nxt.from)>=0?x(years.indexOf(nxt.from)):W)-xx;const label=ERA_SHORT[e.id]||e.name;const fits=label.length*6.6+8<=slot;eras+=`<line class="era-line" x1="${xx.toFixed(1)}" y1="${top-6}" x2="${xx.toFixed(1)}" y2="${H-bottom+4}"/>${fits?`<text class="era-label" x="${(xx+5).toFixed(1)}" y="${top-14}">${esc(label)}</text>`:''}`;}
  let strip='',hits='';for(let i=i0;i<=i1;i++){const w=slotW;strip+=`<rect x="${(x(i)-w/2).toFixed(1)}" y="${H-bottom+8}" width="${Math.max(1,w-1).toFixed(1)}" height="8" fill="${champs[i].t?color(champs[i].t):'#333'}" rx="1"><title>${years[i]} · ${esc(champs[i].d?name(champs[i].d):'—')} · ${esc(champs[i].t?tn(champs[i].t):'')}</title></rect>`;
    hits+=`<rect class="yearhit" data-y="${years[i]}" x="${(x(i)-w/2).toFixed(1)}" y="0" width="${w.toFixed(1)}" height="${H}"/>`;}
  const si=years.indexOf(state.year);const selX=n>1&&!state.whole&&si>=i0&&si<=i1?x(si):-10;
  svg.innerHTML=`<g id="bands">${bands}</g>${eras}<g>${strip}</g><line class="cursor" id="riverCursor" x1="0" y1="${top-4}" x2="0" y2="${H-bottom+4}"/><line x1="${selX.toFixed(1)}" y1="${top-4}" x2="${selX.toFixed(1)}" y2="${H-bottom+16}" stroke="var(--accent)" stroke-width="2" pointer-events="none"/><g id="hits">${hits}</g>`;
  $('#riverStage').classList.toggle('hasfocus',!!state.focusTeam);
  const axisYears=era?years.slice(i0,i1+1).filter((y,k,arr)=>arr.length<=14||k%Math.ceil(arr.length/12)===0||k===arr.length-1):[1950,1960,1970,1980,1990,2000,2010,2020,2026];
  $('#riverAxis').innerHTML=axisYears.map(y=>`<span>${y}</span>`).join('');
  const legend=$('#riverLegend');const scoreOf=era?eraTotal:teamTotal;const topN=[...drawTeams].sort((a,b)=>(scoreOf[b]||0)-(scoreOf[a]||0)).slice(0,14);
  if(state.focusTeam&&!(scoreOf[state.focusTeam]>0))state.focusTeam=null;
  legend.innerHTML=topN.map(t=>`<button type="button" data-t="${esc(t)}" class="${state.focusTeam===t?'on':''}"><i style="background:${color(t)}"></i>${esc(tn(t))}</button>`).join('');
  if(!legend.dataset.built){legend.dataset.built='1';legend.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();});}
  const tip=$('#riverTip'),stage=$('#riverStage');
  svg.onmousemove=e=>{const hit=e.target.closest('.yearhit');if(!hit){tip.classList.remove('show');$('#riverCursor').style.opacity=0;return;}const y=+hit.dataset.y,i=years.indexOf(y);const cx=x(i);const cur=$('#riverCursor');cur.setAttribute('x1',cx);cur.setAttribute('x2',cx);cur.style.opacity=1;
    const top5=Object.entries(shares[i]).sort((a,b)=>b[1]-a[1]).slice(0,5);const c=champs[i];
    tip.innerHTML=`<div class="yr">${y}</div><div class="small muted" style="margin:2px 0 8px">${c.races} Grands Prix · champion <b style="color:var(--ink)">${esc(c.d?name(c.d):'—')}</b></div>${top5.map(([t,p])=>`<div class="row"><span><i class="sw" style="background:${color(t)}"></i>${esc(tn(t))}</span><span>${totals[i]?Math.round(p/totals[i]*100):0}%</span></div>`).join('')}<div class="small dim" style="margin-top:8px">Share of all points scored that season · click to open</div>`;
    const r=stage.getBoundingClientRect();let px=e.clientX-r.left;px=Math.max(150,Math.min(r.width-150,px));tip.style.left=px+'px';tip.style.top='12px';tip.classList.add('show');};
  svg.onmouseleave=()=>{tip.classList.remove('show');$('#riverCursor').style.opacity=0;};
  svg.onclick=e=>{const b=e.target.closest('.band');const hit=e.target.closest('.yearhit');if(hit){setSeason(+hit.dataset.y,true);}else if(b){state.focusTeam=state.focusTeam===b.dataset.t?null:b.dataset.t;drawRiver();}};
}

/* ---------- the Grid ---------- */
function circuitModel(){const rr=eraRaces();const m={};for(const r of rr){let c=m[r.cid]||(m[r.cid]={cid:r.cid,count:0,first:r.year,last:r.year,wins:{},layout:null,name:r.circuit,country:r.country,place:r.place});c.count++;c.first=Math.min(c.first,r.year);c.last=Math.max(c.last,r.year);c.layout=r.layout||c.layout;const w=r.rows.find(x=>x.cw);if(w)c.wins[w.t]=(c.wins[w.t]||0)+1;}
  return Object.values(m).map(c=>({...c,top:Object.entries(c.wins).sort((a,b)=>b[1]-a[1])[0]?.[0]||null}));}
function drawGrid(){const list=circuitModel();const q=state.gridFind.trim().toLowerCase();let shown=list.filter(c=>!q||(c.name+' '+c.country+' '+c.place).toLowerCase().includes(q));
  const sorters={count:(a,b)=>b.count-a.count||a.name.localeCompare(b.name),name:(a,b)=>a.name.localeCompare(b.name),country:(a,b)=>a.country.localeCompare(b.country)||b.count-a.count,recent:(a,b)=>b.last-a.last||b.count-a.count};shown.sort(sorters[state.gridSort]);
  const bigN=state.gridSort==='count'&&!q?6:0;
  $('#gridLede').textContent=`${list.length} circuits have hosted a Grand Prix in ${eraLabel().replace(' · ',', ')}. Each outline is drawn from the circuit’s own survey line, lit in the colours of its most successful constructor there; the size follows how often the calendar returned.`;
  $('#circuits').innerHTML=shown.map((c,i)=>`<button type="button" class="circ${i<bigN?' big':''}" data-cid="${esc(c.cid)}" style="${c.top?teamVar(c.top):'--team:#8b9099'}" title="${esc(c.name)} · ${c.count} Grands Prix · ${c.first}–${c.last}${c.top?' · most wins: '+esc(tn(c.top)):''}"><span class="ct">${esc(c.country)}</span><span class="n">${c.count}</span>${outline(c.layout,{lap:!RM,delay:(i%9)-9})}<span class="nm">${esc(c.name)}</span></button>`).join('')||`<p class="muted">No circuit matches.</p>`;}

/* ---------- Stage: tabs, era strip, era context ---------- */
const TABS=[['season','Season'],['race','Race'],['drivers','Drivers'],['teams','Constructors'],['circuits','Circuits'],['records','Records'],['barcode','Barcode'],['duel','Duel']];
function drawTabs(){$('#tabs').innerHTML=TABS.map(([id,l])=>`<button type="button" role="tab" data-tab="${id}" aria-pressed="${state.tab===id}">${l}</button>`).join('');
  $('#stageStatus').textContent=(state.tab==='season'||state.tab==='race')&&!state.whole?`${state.year} · ${eraOf(state.year)?.name||''}`:eraLabel();}
function drawEraStrip(preview){const strip=$('#eraStrip');if(!strip.children.length)strip.innerHTML=ERAS.map(e=>`<button type="button" style="--w:${e.to-e.from+1}" data-era="${e.id}" title="${esc(e.name)} · ${e.from}–${e.to}" aria-label="${esc(e.name)} ${e.from}–${e.to}"></button>`).join('');
  for(const b of strip.children){b.classList.toggle('on',state.era===b.dataset.era);b.classList.toggle('demo',preview===b.dataset.era);}
  const e=preview?ERAS.find(x=>x.id===preview):state.era==='all'?eraOf(state.year):ERAS.find(x=>x.id===state.era);
  $('#eraCaption').innerHTML=`<span><b>${esc(e.name)}</b> · ${e.from}–${e.to}</span><span class="dim">${state.era===e.id?'Lens on · click again to release':'Click a segment to focus the whole page on that era'}</span>`;
  const ctx=$('#eraContext');ctx.innerHTML=`<div class="era-car">${e.car.svg}</div><div><p class="eyebrow">${state.era===e.id?'Era lens':preview?'Era':'Era of the selected season'} · ${e.from}–${e.to}</p><h3>${esc(e.name)}</h3><p>${esc(e.text)}</p><div class="chips">${e.car.features.map(f=>`<span>${esc(f)}</span>`).join('')}</div><p class="small dim" style="margin:10px 0 0">${esc(e.car.label)} · schematic outline, not a specific car${e.car.source?` · <a href="${esc(e.car.source)}" target="_blank" rel="noopener">reference ↗</a>`:''}</p></div>`;}
/* Attract mode: the strip walks through the eras, one every few seconds, until the visitor touches it. */
const tour={i:-1,timer:null,visible:false,stopped:RM};
function tourStep(){if(tour.stopped||!tour.visible)return;tour.i=(tour.i+1)%ERAS.length;const ctx=$('#eraContext');ctx.classList.add('swap');setTimeout(()=>{if(tour.stopped)return;drawEraStrip(ERAS[tour.i].id);ctx.classList.remove('swap');},260);tour.timer=setTimeout(tourStep,4200);}
function tourStart(){if(tour.stopped||tour.timer)return;tour.timer=setTimeout(tourStep,1800);}
function tourPause(){clearTimeout(tour.timer);tour.timer=null;}
function tourStop(){if(tour.stopped)return;tour.stopped=true;tourPause();$('#eraContext').classList.remove('swap');drawEraStrip();}
/* ---------- Season ---------- */
function seasonStandings(s){
  const st=standingsOf(s);const dr=st.drivers.map(d=>({id:d.id,p:d.p,pts:d.pts,wins:d.wins,teams:d.teams,team:d.teams?.[0]}));const derivedD=st.derived;
  let tm,derived=false;if(s.teams&&s.teams.length)tm=s.teams.map(t=>({id:t.id,p:t.p,pts:t.pts,wins:t.wins}));else{derived=true;const m={};for(const r of s.races){for(const x of r.rows){let a=m[x.t]||(m[x.t]={id:x.t,pts:0,wins:0});a.pts+=x.pts;a.wins+=x.cw;}}tm=Object.values(m).sort((a,b)=>b.pts-a.pts||b.wins-a.wins).map((t,i)=>({...t,p:String(i+1)}));}
  return {dr,tm,derived,derivedD};}
function cumulative(s,top=8){const done=s.races.filter(r=>r.rows.length);const sd=standingsOf(s).drivers;const ids=sd.slice(0,top).map(d=>d.id);const series=ids.map(id=>({id,team:sd.find(d=>d.id===id).teams?.[0],pts:[0]}));
  for(const r of done){for(const sr of series){const x=r.rows.find(x=>x.d===sr.id);const sp=r.sprint.find(x=>x.d===sr.id);sr.pts.push(sr.pts[sr.pts.length-1]+(x?x.pts:0)+(sp?sp.pts:0));}}
  return {series,rounds:done.map(r=>r.round)};}
function drawChart(el,series,rounds,labelOf,xl=r=>'R'+r){const box=el.getBoundingClientRect(),W=Math.max(300,box.width),H=Math.max(200,box.height);const padL=34,padR=90,padT=14,padB=26;const max=Math.max(1,...series.flatMap(s=>s.pts));const n=rounds.length;const x=i=>padL+(n?i*(W-padL-padR)/n:0),y=v=>padT+(H-padT-padB)*(1-v/max);
  let g='';const step=max>200?100:max>60?25:max>20?10:5;for(let v=0;v<=max;v+=step)g+=`<line class="gridl" x1="${padL}" x2="${W-padR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}"/><text class="lb" x="${padL-6}" y="${(y(v)+3).toFixed(1)}" text-anchor="end">${v}</text>`;
  for(let i=0;i<n;i++)if(n<=30||i%2===0)g+=`<text class="lb" x="${x(i+1).toFixed(1)}" y="${H-8}" text-anchor="middle">${xl(rounds[i])}</text>`;
  const paths=series.map((s,k)=>{const d=s.pts.map((v,i)=>(i?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)).join('');const last=s.pts[s.pts.length-1];return `<path class="ser" d="${d}" style="--c:${color(s.team)}"><title>${esc(labelOf(s.id))} · ${fmt(last)}</title></path><text class="end" x="${(x(n)+6).toFixed(1)}" y="${(y(last)+4-(k%2?0:0)).toFixed(1)}" style="--c:${color(s.team)}">${esc(labelOf(s.id))} ${fmt(last)}</text>`;}).join('');
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cumulative points by round">${g}${paths}</svg>`;}
function seasonView(){if(state.whole)return eraView();const s=byYear[state.year];const {dr,tm,derived,derivedD}=seasonStandings(s);const done=s.races.filter(r=>r.rows.length);const champ=dr[0];const ct=tm[0];const cteam=champ?.team;const partial=String(s.year)===(DATA.cutoff||'').slice(-4);
  const wins=new Set(done.map(r=>r.rows.find(x=>x.dw)?.d).filter(Boolean)).size;const teamsWon=new Set(done.map(r=>r.rows.find(x=>x.cw)?.t).filter(Boolean)).size;
  const podium=dr.slice(0,3);const maxPts=podium[0]?.pts||1;const order=[podium[1],podium[0],podium[2]];
  const head=`<div class="season-head"><div class="champ-card" style="${cteam?`--accent:${color(cteam)};--on-accent:${onColor(color(cteam))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">${partial?'Season in progress · standings as at '+esc(DATA.cutoff):'Drivers’ champion'}</p><div class="yr">${s.year}</div>${champ?`<div class="who"><small>${partial?'Leads the standings':derivedD?'Most race points':'Champion'}</small>${esc(name(champ.id))}</div><div class="team"><i></i>${esc(champ.teams.map(tn).join(' / '))}</div><div class="facts"><div><b>${fmt(champ.pts)}</b>points</div><div><b>${champ.wins}</b>wins</div><div><b>${done.length}</b>Grands Prix${done.length<s.races.length?` of ${s.races.length}`:''}</div><div><b>${wins}</b>race winners</div></div>`:'<div class="who">No results yet</div>'}${ct?`<p class="small" style="margin:18px 0 0;color:var(--ink);opacity:.8">Constructors: <b>${esc(tn(ct.id))}</b> · ${fmt(ct.pts)} pts${derived?' · <span class="dim">from race points; no constructors’ championship was awarded</span>':''}</p>`:''}</div>
  <div><div class="podium">${order.map((d,i)=>d?`<button type="button" class="step p${d.p} bar" data-driver="${esc(d.id)}" style="--h:${Math.round(120+120*d.pts/maxPts)}px;${teamVar(d.team)};display:flex"><span class="pos">${esc(d.p)}</span><span class="nm">${esc(short(d.id))}</span><span class="pt">${fmt(d.pts)} pts · ${d.wins} wins · ${esc(tn(d.team))}</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const cal=`<div class="h3"><span>Calendar</span><small>${partial?done.length+' rounds run so far':done.length+' rounds'} · click a race to replay it</small></div><div class="calendar">${s.races.map(r=>{const w=r.rows.find(x=>x.dw);return `<button type="button" class="cal${r.rows.length?'':' future'}${state.race===r.round&&state.tab==='race'?' on':''}" data-race="${r.round}" style="${w?teamVar(w.t):'--team:#5b616b'}"><div class="rd">R${r.round} · ${esc(r.date.slice(5))}</div>${outline(r.layout)}<div class="nm">${esc(r.name.replace(' Grand Prix',' GP'))}</div><div class="w">${w?esc(short(w.d)):'not yet run'}</div></button>`;}).join('')}</div>`;
  const bars=(rows,by)=>`<div class="board">${rows.map((r,i)=>`<button type="button" class="bar" data-${by}="${esc(r.id)}" style="--i:${i};${teamVar(by==='driver'?r.team:r.id)}"><span class="rk">${esc(r.p)}</span><span><span class="lab"><span>${esc(by==='driver'?name(r.id):tn(r.id))}<small> ${esc(by==='driver'?r.teams.map(tn).join(' / '):'')}</small></span><small>${r.wins} win${r.wins===1?'':'s'}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*r.pts/(rows[0]?.pts||1))}%"></span></span></span><span class="val">${fmt(r.pts)}</span></button>`).join('')}</div>`;
  const cum=cumulative(s);
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Drivers’ standings</span><small>${derivedD?'ordered by race points — this archive holds no published table for '+s.year+'; the title that year counted only the best four results':'published standings'}</small></div>${bars(dr,'driver')}</div><div class="panel"><div class="h3"><span>Constructors’ standings</span><small>${derived?'from race points':'published standings'}</small></div>${bars(tm,'team')}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>The title fight, round by round</span><small>cumulative GP + sprint points, top ${cum.series.length}</small></div><div class="chart" id="cumChart"></div></div>`;
  $('#view').innerHTML=head+cal+body;drawChart($('#cumChart'),cum.series,cum.rounds,short);}

/* ---------- Whole era, combined ---------- */
function eraView(){const seasons=eraSeasons();const rr=eraRaces();const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);const label=e?e.name:'All eras';const span=`${seasons[0].year}–${seasons[seasons.length-1].year}`;
  const cutYear=+(DATA.cutoff||'').slice(-4);const dr=enriched(rr,'d').sort((a,b)=>b.total-a.total||b.wins-a.wins);const tm=enriched(rr,'t').sort((a,b)=>b.total-a.total||b.wins-a.wins);
  const titles={},ttitles={};const roll=seasons.map(s=>{const st=standingsOf(s);const c=st.drivers[0];const ct=s.teams?.[0];const partial=s.year===cutYear;if(c&&!partial)titles[c.id]=(titles[c.id]||0)+1;if(ct&&!partial)ttitles[ct.id]=(ttitles[ct.id]||0)+1;return {year:s.year,d:c?.id,t:c?champTeam(s):null,ct:ct?.id,partial,derived:st.derived,races:s.races.filter(r=>r.rows.length).length};});
  const winners=new Set(rr.map(r=>r.rows.find(x=>x.dw)?.d).filter(Boolean)).size;const circuits=new Set(rr.map(r=>r.cid)).size;
  const podium=[...dr].sort((a,b)=>(titles[b.id]||0)-(titles[a.id]||0)||b.wins-a.wins||b.total-a.total).slice(0,3);const order=[podium[1],podium[0],podium[2]];const maxW=Math.max(1,podium[0]?.wins||1);
  const topTeam=tm[0]?.id;
  const head=`<div class="season-head"><div class="champ-card" style="${topTeam?`--accent:${color(topTeam)};--on-accent:${onColor(color(topTeam))}`:''}"><p class="eyebrow" style="color:var(--ink);opacity:.7">Whole era, combined · ${seasons.length} seasons</p><div class="yr" style="font-size:clamp(44px,6vw,84px)">${span}</div><div class="who"><small>${esc(label)}</small>${esc(dr[0]?name(dr[0].id):'—')}</div><div class="team"><i></i>most race points in the era · ${esc(dr[0]?tn([...dr[0].teams].pop()):'')}</div><div class="facts"><div><b>${rr.length}</b>Grands Prix</div><div><b>${winners}</b>race winners</div><div><b>${circuits}</b>circuits</div><div><b>${tm.length}</b>constructors</div></div><p class="small" style="margin:18px 0 0;color:var(--ink);opacity:.8">Constructors: <b>${esc(topTeam?tn(topTeam):'—')}</b> · ${fmt(tm[0]?.total||0)} race points${ttitles[topTeam]?` · ${ttitles[topTeam]} title${ttitles[topTeam]===1?'':'s'}`:''}<br><span class="dim">Podium ranked by titles in the era, then wins</span></p></div>
  <div><div class="podium">${order.map(d=>d?`<button type="button" class="step p${podium.indexOf(d)+1} bar" data-driver="${esc(d.id)}" style="--h:${Math.round(120+120*d.wins/maxW)}px;${teamVar([...d.teams].pop())};display:flex"><span class="pos">${podium.indexOf(d)+1}</span><span class="nm">${esc(short(d.id))}</span><span class="pt">${titles[d.id]||0} title${titles[d.id]===1?'':'s'} · ${d.wins} wins · ${fmt(d.total)} pts</span></button>`:'<div></div>').join('')}<div class="base"></div></div></div></div>`;
  const rollHtml=`<div class="h3"><span>Champions, season by season</span><small>click a season to open it</small></div><div class="calendar">${roll.map(c=>`<button type="button" class="cal" data-year="${c.year}" style="${c.t?teamVar(c.t):'--team:#5b616b'}"><div class="rd">${c.year} · ${c.races} GP</div><div class="nm" style="font-size:16px;margin-top:10px;color:var(--team)">${esc(c.d?short(c.d):'—')}</div><div class="w" style="color:var(--muted)">${c.partial?'leads, in progress':c.derived?'most race points':esc(c.t?tn(c.t):'')}</div><div class="w">${c.ct?'⚑ '+esc(tn(c.ct)):''}</div></button>`).join('')}</div>`;
  const bars=(rows,by)=>`<div class="board">${rows.slice(0,20).map((a,i)=>`<button type="button" class="bar" data-${by}="${esc(a.id)}" style="--i:${i};${teamVar(by==='driver'?[...a.teams].pop():a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(by==='driver'?name(a.id):tn(a.id))}<small> ${by==='driver'?esc([...a.teams].map(tn).slice(0,3).join(' / ')):a.first+'–'+a.last}</small></span><small>${(by==='driver'?titles:ttitles)[a.id]?((by==='driver'?titles:ttitles)[a.id]+' title'+((by==='driver'?titles:ttitles)[a.id]===1?'':'s')+' · '):''}${a.wins} win${a.wins===1?'':'s'}</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*a.total/(rows[0]?.total||1))}%"></span></span></span><span class="val">${fmt(a.total)}</span></button>`).join('')}</div>`;
  const top8=dr.slice(0,8);const series=top8.map(a=>({id:a.id,team:[...a.teams].pop(),pts:[0]}));for(const s of seasons){for(const sr of series){let w=0;for(const r of s.races)for(const x of r.rows)if(x.d===sr.id&&x.dw)w++;sr.pts.push(sr.pts[sr.pts.length-1]+w);}}
  const body=`<div class="two" style="margin-top:26px"><div class="panel"><div class="h3"><span>Drivers across the era</span><small>GP + sprint points summed over ${seasons.length} seasons</small></div>${bars(dr,'driver')}</div><div class="panel"><div class="h3"><span>Constructors across the era</span><small>race points summed; titles from published tables</small></div>${bars(tm,'team')}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Wins, season by season</span><small>cumulative Grand Prix wins, top ${series.length} by points</small></div><div class="chart" id="cumChart"></div></div><p class="small dim" style="margin-top:12px">Published championship tables are per season, so era totals here are race points as awarded; drop-score rules in 1950–1990 mean they can exceed the published season figures.</p>`;
  $('#view').innerHTML=head+rollHtml+body;drawChart($('#cumChart'),series,seasons.map(s=>s.year),short,y=>String(y).slice(2));}
function eraRacesView(){const rr=eraRaces();$('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Every Grand Prix · ${esc(eraLabel())}</span><small>${rr.length} races · click one to replay it</small></div><div class="tablewrap"><table><tr><th>Season</th><th>Rd</th><th>Race</th><th>Circuit</th><th>Winner</th><th>Constructor</th><th>Grid P1</th><th>Fastest lap</th></tr>${rr.slice().reverse().map(r=>{const w=r.rows.find(x=>x.dw);const p=r.rows.find(x=>x.g===1);const f=r.rows.find(x=>x.fr===1);return `<tr><td><a href="#" data-year="${r.year}" data-round="${r.round}" style="color:inherit">${r.year}</a></td><td>${r.round}</td><td><a href="#" data-year="${r.year}" data-round="${r.round}" style="color:inherit">${esc(r.name)}</a></td><td>${esc(r.circuit)}</td><td>${w?esc(name(w.d)):'—'}</td><td>${w?`<i class="dot" style="${teamVar(w.t)}"></i>${esc(tn(w.t))}`:'—'}</td><td>${p?esc(short(p.d)):'—'}</td><td>${f?esc(f.fl)+' · '+esc(short(f.d)):'—'}</td></tr>`;}).join('')}</table></div>`;}

/* ---------- Race: replay + timing tower ---------- */
let replay=null;
function stopReplay(){if(replay){cancelAnimationFrame(replay.raf);replay=null;}}
function raceView(){if(state.whole)return eraRacesView();const s=byYear[state.year];let r=s.races.find(x=>x.round===state.race)||s.races.find(x=>x.rows.length)||s.races[0];if(!r){$('#view').innerHTML='<p class="muted">No races.</p>';return;}state.race=r.round;
  const winner=r.rows.find(x=>x.dw);const L=r.scheduledLaps||Math.max(1,...r.rows.map(x=>x.laps));const fl=r.rows.find(x=>x.fr===1);
  const nav=`<div class="chiplist" style="margin-top:20px">${s.races.map(x=>`<button type="button" class="chip${x.round===r.round?' on':''}" data-race="${x.round}" style="${x.round===r.round?'border-color:var(--accent);color:var(--accent)':''}${x.rows.length?'':';opacity:.45'}"><i style="--c:${(w=>w?color(w.t):'#444')(x.rows.find(y=>y.dw))}"></i>R${x.round} ${esc(x.name.replace(' Grand Prix',''))}</button>`).join('')}</div>`;
  const meta=`<div class="kpis" style="margin-top:18px"><div class="kpi"><span>Date</span><b style="font-size:22px">${esc(r.date)}</b><small>Round ${r.round} of ${s.races.length}</small></div><div class="kpi"><span>Circuit</span><b style="font-size:22px"><a href="#" data-circuit="${esc(r.cid)}" style="color:inherit;text-decoration:none">${esc(r.circuit)}</a></b><small>${esc(r.place)}, ${esc(r.country)}</small></div><div class="kpi"><span>Lap</span><b>${r.length?r.length.toFixed(3)+' km':'—'}</b><small>${r.turns||'—'} turns · ${esc((r.trackType||'').toLowerCase())} · ${esc((r.direction||'').toLowerCase().replace('_',' '))}</small></div><div class="kpi"><span>Distance</span><b>${r.distance?Math.round(r.distance)+' km':'—'}</b><small>${r.scheduledLaps||'—'} laps scheduled</small></div><div class="kpi"><span>Fastest lap</span><b style="font-size:24px">${esc(fl?.fl||'—')}</b><small>${fl?esc(short(fl.d)):'not recorded'}</small></div></div>`;
  if(!r.rows.length){stopReplay();$('#view').innerHTML=`${nav}<div class="panel" style="margin-top:20px"><div class="h3"><span>${esc(r.name)} · ${s.year}</span><small>not yet run</small></div><div style="max-width:320px">${outline(r.layout,{lap:!RM})}</div></div>${meta}`;return;}
  const d=pathD(r.layout);
  const cars=r.rows.map((x,i)=>`<g class="car" data-i="${i}" style="opacity:${0}"><circle r="11" fill="${color(x.t)}"/><text>${esc(code(x.d))}</text></g>`).join('');
  const rep=`<div class="replay" id="replay"><div class="hud"><div><h3>${esc(r.name)}</h3><div class="sub">${s.year} · ${esc(r.circuit)} · ${r.rows.length} cars · ${L} laps</div></div><div class="flag"></div></div><div class="track"><svg viewBox="-30 -30 560 560" id="trackSvg"><path class="base" d="${d}"/><path class="line" d="${d}" id="trackPath"/><path class="kerb" d="${d}"/><g id="cars">${cars}</g></svg></div>
  <div class="ctl"><button type="button" class="btn on" id="playBtn" aria-label="Play or pause">▶ Play</button><input type="range" id="scrub" min="0" max="1000" value="0" aria-label="Race progress"><span class="lapct" id="lapct">Lap 0 / ${L}</span><select id="speed" aria-label="Replay speed"><option value="1" selected>Slow</option><option value="2">Medium</option><option value="4">Quick</option></select></div><p class="small dim" style="margin:10px 0 0">A symbolic replay, not a timing feed: cars leave their grid slots and circulate slowly on the real circuit line until their recorded lap count, retirements fading where they stopped. Spacing follows the finishing order.</p></div>`;
  const rows=r.rows;const tower=`<div class="tower"><div class="th"><span>Pos</span><span></span><span>Driver</span><span style="text-align:center">Grid</span><span style="text-align:right">Gap</span><span style="text-align:right">Pts</span><span style="text-align:right">Status</span></div>${rows.map((x,i)=>{const gain=x.g?x.g-x.p:null;return `<div class="tr p${x.p}${finished(x)?'':' dnf'}" style="--i:${i};${teamVar(x.t)}"><span class="pos">${esc(x.label)}</span><span class="code">${esc(code(x.d))}</span><span class="name"><a href="#" data-driver="${esc(x.d)}" style="color:inherit;text-decoration:none">${esc(name(x.d))}</a><small>${esc(tn(x.t))}</small></span><span class="delta ${gain>0?'up':gain<0?'down':''}">${x.g?`${x.g}${gain?`<small style="font-weight:400"> ${gain>0?'▲':'▼'}${Math.abs(gain)}</small>`:''}`:'—'}</span><span class="gap">${esc(x.time||'')}</span><span class="pts">${x.pts?fmt(x.pts):''}</span><span class="st ${x.fr===1?'fl':''}">${x.fr===1?'★ '+esc(x.fl):esc(x.status)}</span></div>`;}).join('')}</div>`;
  const sprint=r.sprint.length?`<div class="panel" style="margin-top:20px"><div class="h3"><span>Sprint</span><small>separate classification</small></div><div class="tablewrap"><table><tr><th>Pos</th><th>Driver</th><th>Constructor</th><th>Grid</th><th>Laps</th><th>Time</th><th>Status</th><th>Pts</th></tr>${r.sprint.map(x=>`<tr><td>${esc(x.label)}</td><td>${esc(name(x.d))}</td><td><i class="dot" style="${teamVar(x.t)}"></i>${esc(tn(x.t))}</td><td>${x.g||'—'}</td><td>${x.laps}</td><td>${esc(x.time||'—')}</td><td>${esc(x.status)}</td><td>${fmt(x.pts)}</td></tr>`).join('')}</table></div></div>`:'';
  const links=`<p class="small dim" style="margin-top:14px">${r.url?`<a href="${esc(r.url)}" target="_blank" rel="noopener">Race on Wikipedia ↗</a> · `:''}${r.circuitUrl?`<a href="${esc(r.circuitUrl)}" target="_blank" rel="noopener">Circuit ↗</a> · `:''}${r.trackSource?`<a href="${esc(r.trackSource)}" target="_blank" rel="noopener">Track record (F1DB) ↗</a>`:''}</p>`;
  $('#view').innerHTML=`${nav}<div class="race">${rep}<div><div class="h3"><span>Classification</span><small>${winner?'won by '+esc(name(winner.d)):''}</small></div>${tower}</div></div>${meta}${sprint}${links}`;
  startReplay(r,L);}
function startReplay(r,L){stopReplay();const path=$('#trackPath');if(!path||!path.getTotalLength)return;const len=path.getTotalLength();const cars=$$('#cars .car');const rows=r.rows;const nFin=rows.filter(finished).length||1;
  const model=rows.map((x,i)=>{const fin=finished(x);const laps=Math.max(0,Math.min(x.laps||0,L));const stopAt=laps/L;const speed=fin?1-0.012*(x.p-1)/Math.max(1,nFin):1;const grid=x.g?x.g:rows.length;return {x,fin,stopAt,speed,start:-(grid-1)*0.0065,el:cars[i]};});
  const place=t=>{for(const m of model){const tt=Math.min(t,m.stopAt);const lapsRun=tt*L;const frac=((m.start+lapsRun*m.speed)%1+1)%1;const p=path.getPointAtLength(frac*len);m.el.setAttribute('transform',`translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})`);const dead=!m.fin&&t>=m.stopAt+0.002;m.el.style.opacity=dead?.22:1;}
    $('#lapct').textContent=`Lap ${Math.min(L,Math.floor(t*L+1e-9))} / ${L}`;$('#scrub').value=Math.round(t*1000);$('#replay').classList.toggle('done',t>=1);};
  const rp={t:0,playing:!RM,raf:0,last:0,dur:150000};replay=rp;
  const tick=now=>{if(replay!==rp)return;if(rp.playing){const sp=+$('#speed').value;if(rp.last)rp.t=Math.min(1,rp.t+(now-rp.last)*sp/rp.dur);rp.last=now;place(rp.t);if(rp.t>=1){rp.playing=false;$('#playBtn').textContent='↻ Replay';}}else rp.last=now;rp.raf=requestAnimationFrame(tick);};
  place(0);$('#playBtn').textContent=rp.playing?'❚❚ Pause':'▶ Play';rp.raf=requestAnimationFrame(tick);
  $('#playBtn').onclick=()=>{if(rp.t>=1){rp.t=0;}rp.playing=!rp.playing;$('#playBtn').textContent=rp.playing?'❚❚ Pause':'▶ Play';};
  $('#scrub').oninput=e=>{rp.t=+e.target.value/1000;place(rp.t);};}

/* ---------- Drivers & constructors ---------- */
function radar(el,axes,a,b){const W=260,H=260,cx=130,cy=130,R=96,n=axes.length;const pt=(i,v)=>{const ang=-Math.PI/2+i*2*Math.PI/n;return [cx+Math.cos(ang)*R*v,cy+Math.sin(ang)*R*v];};
  let g='';for(const k of [.25,.5,.75,1])g+=`<polygon class="ring" points="${axes.map((_,i)=>pt(i,k).map(v=>v.toFixed(1)).join(',')).join(' ')}"/>`;for(let i=0;i<n;i++){const [x,y]=pt(i,1);g+=`<line class="axis" x1="${cx}" y1="${cy}" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/>`;const [lx,ly]=pt(i,1.24);g+=`<text class="lbl" x="${lx.toFixed(1)}" y="${(ly+3).toFixed(1)}">${esc(axes[i].label)}</text>`;}
  const poly=(vals,cls)=>`<polygon class="poly ${cls}" points="${vals.map((v,i)=>pt(i,Math.max(0,Math.min(1,v))).map(q=>q.toFixed(1)).join(',')).join(' ')}"/>`;
  el.innerHTML=`<svg viewBox="0 0 ${W} ${H}">${g}${poly(a,'a')}${b?poly(b,'b'):''}</svg>`;}
const AXES=[{k:'wins',label:'Wins'},{k:'podiums',label:'Podiums'},{k:'grid1',label:'Grid P1'},{k:'fl',label:'Fast laps'},{k:'total',label:'Points'},{k:'winRate',label:'Win %'},{k:'finishRate',label:'Finish %'}];
function normAxes(list){const max={};for(const ax of AXES)max[ax.k]=Math.max(1,...list.map(a=>a[ax.k]));return a=>AXES.map(ax=>a[ax.k]/max[ax.k]);}
function listView(by){const rr=eraRaces();const list=enriched(rr,by);const lens=state.lens;const minEntries=/Rate/.test(lens)?(by==='d'?20:20):0;const rows=list.filter(a=>a.entries>=minEntries).sort((a,b)=>b[lens]-a[lens]||b.wins-a.wins).slice(0,30);const max=rows[0]?.[lens]||1;const q=(state.gridFind2||'').toLowerCase();
  const lensSel=`<select id="lens" aria-label="Lens">${Object.entries(LENSES).map(([k,v])=>`<option value="${k}" ${k===lens?'selected':''}>${v[0]}</option>`).join('')}</select>`;
  const found=q?list.filter(a=>(by==='d'?name(a.id):tn(a.id)).toLowerCase().includes(q)).sort((a,b)=>b.total-a.total).slice(0,12):[];
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>${by==='d'?'Drivers':'Constructors'} · ${esc(eraLabel())}</span><small>${list.length} ${by==='d'?'drivers':'constructors'} · ${rr.length} Grands Prix</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px"><input type="search" id="find2" placeholder="Search ${by==='d'?'a driver':'a constructor'}" value="${esc(state.gridFind2||'')}" aria-label="Search">${lensSel}<span class="small muted">${esc(LENSES[lens][1])}${minEntries?` Minimum ${minEntries} entries.`:''}</span></div>${q?`<div class="chiplist" style="margin-bottom:14px">${found.map(a=>`<button type="button" class="chip" data-${by==='d'?'driver':'team'}="${esc(a.id)}"><i style="--c:${color(by==='d'?[...a.teams].pop():a.id)}"></i>${esc(by==='d'?name(a.id):tn(a.id))}</button>`).join('')||'<span class="muted small">No match.</span>'}</div>`:''}<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-${by==='d'?'driver':'team'}="${esc(a.id)}" style="--i:${i};${teamVar(by==='d'?[...a.teams].pop():a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(by==='d'?name(a.id):tn(a.id))}<small> ${a.first}–${a.last}</small></span><small>${a.wins} wins · ${a.races.size} GPs</small></span><span class="trk"><span class="fill" style="--w:${Math.round(100*a[lens]/max)}%"></span></span></span><span class="val">${fmt(a[lens])}${/Rate/.test(lens)?'%':''}</span></button>`).join('')}</div></div>`;}
function seasonsTable(id,by){const out=[];for(const s of S){if(by==='d'){const d=standingsOf(s).drivers.find(x=>x.id===id);const rr=s.races.filter(r=>r.rows.some(x=>x.d===id));if(!d&&!rr.length)continue;const wins=rr.filter(r=>r.rows.some(x=>x.d===id&&x.dw)).length;const pod=rr.filter(r=>r.rows.some(x=>x.d===id&&x.dp)).length;out.push({year:s.year,p:d?.p||'—',pts:d?.pts??rr.reduce((a,r)=>a+(r.rows.find(x=>x.d===id)?.pts||0),0),wins,pod,teams:d?.teams||[...new Set(rr.flatMap(r=>r.rows.filter(x=>x.d===id).map(x=>x.t)))],gps:rr.length});}
    else{const t=s.teams?.find(x=>x.id===id);const rr=s.races.filter(r=>r.rows.some(x=>x.t===id));if(!t&&!rr.length)continue;const wins=rr.filter(r=>r.rows.some(x=>x.t===id&&x.cw)).length;const pod=rr.reduce((a,r)=>a+r.rows.filter(x=>x.t===id&&x.cp).length,0);out.push({year:s.year,p:t?.p||'—',pts:t?.pts??rr.reduce((a,r)=>a+r.rows.filter(x=>x.t===id).reduce((b,x)=>b+x.pts,0),0),wins,pod,teams:[...new Set(rr.flatMap(r=>r.rows.filter(x=>x.t===id).map(x=>x.d)))],gps:rr.length});}}
  return out;}
function participantView(id,by){const rr=eraRaces();const all=enriched(rr,by);const a=all.find(x=>x.id===id);const back=`<button type="button" class="btn" data-tab="${by==='d'?'drivers':'teams'}">← All ${by==='d'?'drivers':'constructors'}</button>`;
  if(!a){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(by==='d'?name(id):tn(id))} has no results in ${esc(eraLabel())}. Change the era lens to see them.</p>`;return;}
  const norm=normAxes(all.filter(x=>x.entries>=(by==='d'?10:10)));const mainTeam=by==='d'?[...a.teams].sort((p,q)=>rr.filter(r=>r.rows.some(x=>x.d===id&&x.t===q)).length-rr.filter(r=>r.rows.some(x=>x.d===id&&x.t===p)).length)[0]:id;
  const tbl=seasonsTable(id,by).filter(x=>state.era==='all'||(x.year>=ERAS.find(e=>e.id===state.era).from&&x.year<=ERAS.find(e=>e.id===state.era).to));const titles=tbl.filter(x=>x.p==='1').length;
  const ribbon=rr.filter(r=>r.rows.some(x=>x[by]===id)).map(r=>{const x=r.rows.filter(y=>y[by]===id).sort((p,q)=>p.p-q.p)[0];const c=x.p===1?'var(--gold)':x.p<=3?'var(--silver)':x.p<=10&&x.pts?'#5a6270':finished(x)?'#2a2f39':'#3a1414';return `<i style="--c:${c}" title="${r.year} ${esc(r.name)} · ${esc(x.label)}${x.status!=='Finished'?' · '+esc(x.status):''}"></i>`;}).join('');
  const info=by==='d'?`<p class="muted" style="margin:4px 0 0">${esc(D[id]?.nationality||'')}${D[id]?.dob?' · born '+esc(D[id].dob):''} · #${esc([...new Set(rr.flatMap(r=>r.rows.filter(x=>x.d===id).map(x=>x.num)))].slice(0,4).join(', #'))}</p>`:'';
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;${teamVar(mainTeam)}"><div class="panel"><div class="trace" id="trace"></div><p class="small dim" style="text-align:center;margin:8px 0 0">Form trace · each axis relative to the best in this era lens</p></div>
  <div><p class="eyebrow">${by==='d'?'Driver':'Constructor'} · ${a.first}–${a.last}</p><h2 class="display" style="font-size:clamp(40px,6vw,84px);margin:6px 0 0;color:var(--team);text-shadow:0 0 30px rgba(255,255,255,.18)">${esc(by==='d'?name(id):tn(id))}</h2>${info}
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Titles</span><b>${titles}</b><small>championships in lens</small></div><div class="kpi"><span>Wins</span><b>${a.wins}</b><small>${a.winRate}% of ${by==='d'?'entries':'weekends'}</small></div><div class="kpi"><span>Podiums</span><b>${a.podiums}</b><small>${a.podiumRate}% of entries</small></div><div class="kpi"><span>Grid P1</span><b>${a.grid1}</b><small>first on the grid</small></div><div class="kpi"><span>Fastest laps</span><b>${a.fl}</b></div><div class="kpi"><span>Points</span><b>${fmt(a.total)}</b><small>${fmt(a.gp)} GP${a.sprint?' + '+fmt(a.sprint)+' sprint':''}</small></div><div class="kpi"><span>Grands Prix</span><b>${a.races.size}</b><small>${a.entries} entries · ${a.finishRate}% finish</small></div></div>
  <div class="h3" style="margin-top:20px"><span>Every Grand Prix</span><small>gold win · silver podium · grey points · dark finish · red non-finish</small></div><div class="ribbon">${ribbon}</div>
  <div class="h3" style="margin-top:20px"><span>${by==='d'?'Constructors driven for':'Drivers'}</span></div><div class="chiplist">${[...(by==='d'?a.teams:a.drivers)].map(t=>`<button type="button" class="chip" data-${by==='d'?'team':'driver'}="${esc(t)}"><i style="--c:${color(by==='d'?t:mainTeam)}"></i>${esc(by==='d'?tn(t):name(t))}</button>`).join('')}</div></div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Season by season</span><small>published standings where available</small></div><div class="tablewrap"><table><tr><th>Season</th><th>Pos</th><th>Points</th><th>Wins</th><th>Podiums</th><th>GPs</th><th>${by==='d'?'Constructor':'Drivers'}</th></tr>${tbl.map(x=>`<tr><td><a href="#" data-year="${x.year}" style="color:inherit">${x.year}</a></td><td>${x.p==='1'?'<b style="color:var(--gold)">1 ★</b>':esc(x.p)}</td><td>${fmt(x.pts)}</td><td>${x.wins}</td><td>${x.pod}</td><td>${x.gps}</td><td>${esc(x.teams.map(by==='d'?tn:short).join(', '))}</td></tr>`).join('')}</table></div></div>`;
  radar($('#trace'),AXES,norm(a));}

/* ---------- Circuits ---------- */
function circuitStats(rr){let winners={},constructors={};let gridKnown=rr.filter(r=>r.rows.some(x=>x.g===1));let p1wins=gridKnown.filter(r=>r.rows[0].g===1).length;let entries=rr.flatMap(r=>r.rows.filter(x=>x.ce));let gaps=rr.map(r=>r.rows.find(x=>x.p===2)?.time||'').filter(t=>t.startsWith('+')&&!/lap/i.test(t)).map(lapSeconds).filter(v=>v!==null).sort((a,b)=>a-b);let median=gaps.length?(gaps[Math.floor((gaps.length-1)/2)]+gaps[Math.floor(gaps.length/2)])/2:null;for(const r of rr){for(const w of r.rows){if(w.dw)winners[w.d]=(winners[w.d]||0)+1;if(w.cw)constructors[w.t]=(constructors[w.t]||0)+1;}}return {winners,constructors,p1wins,gridKnown:gridKnown.length,nf:entries.reduce((sum,x)=>sum+x.cn,0),entries:entries.length,median,gapN:gaps.length};}
function circuitsView(){const list=circuitModel().sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Circuits · ${esc(eraLabel())}</span><small>${list.length} venues</small></div><div class="tablewrap"><table><tr><th>Circuit</th><th>Country</th><th>GPs</th><th>Years</th><th>Most wins</th></tr>${list.map(c=>`<tr><td><a href="#" data-circuit="${esc(c.cid)}" style="color:inherit">${esc(c.name)}</a></td><td>${esc(c.country)}</td><td>${c.count}</td><td>${c.first}${c.last!==c.first?'–'+c.last:''}</td><td>${c.top?`<i class="dot" style="${teamVar(c.top)}"></i>${esc(tn(c.top))} (${c.wins[c.top]})`:'—'}</td></tr>`).join('')}</table></div>`;}
function circuitView(cid){const c=CIRC[cid];const rr=eraRaces().filter(r=>r.cid===cid);const back=`<button type="button" class="btn" data-tab="circuits">← All circuits</button>`;
  if(!rr.length){$('#view').innerHTML=`<div style="margin-top:22px">${back}</div><p class="muted" style="margin-top:16px">${esc(c?.name||cid)} hosted no Grand Prix in ${esc(eraLabel())}.</p>`;return;}
  const st=circuitStats(rr);const last=rr[rr.length-1];const topT=Object.entries(st.constructors).sort((a,b)=>b[1]-a[1]);const topD=Object.entries(st.winners).sort((a,b)=>b[1]-a[1]);
  let rec=null;for(const r of rr)for(const x of r.rows){if(x.fr===1){const s=lapSeconds(x.fl);if(s!==null&&(!rec||s<rec.s))rec={s,x,r};}}
  const ribbon=rr.map(r=>{const w=r.rows.find(x=>x.dw);return `<i style="--c:${w?color(w.t):'#333'}" title="${r.year} · ${esc(w?name(w.d):'—')} · ${esc(w?tn(w.t):'')}"></i>`;}).join('');
  const layouts=[...new Set(rr.map(r=>r.layout).filter(Boolean))];
  const bars=(arr,by)=>`<div class="board">${arr.slice(0,8).map(([id,n],i)=>`<button type="button" class="bar" data-${by}="${esc(id)}" style="--i:${i};${teamVar(by==='driver'?(rr.find(r=>r.rows.some(x=>x.d===id&&x.dw))?.rows.find(x=>x.d===id)?.t):id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(by==='driver'?name(id):tn(id))}</span></span><span class="trk"><span class="fill" style="--w:${Math.round(100*n/arr[0][1])}%"></span></span></span><span class="val">${n}</span></button>`).join('')}</div>`;
  $('#view').innerHTML=`<div style="margin-top:22px;display:flex;gap:10px;flex-wrap:wrap;align-items:center">${back}<span class="small muted">${esc(eraLabel())}</span></div>
  <div class="card" style="margin-top:18px;grid-template-columns:minmax(240px,380px) 1fr;${topT[0]?teamVar(topT[0][0]):''}"><div class="panel circ" style="aspect-ratio:auto;cursor:default;transform:none">${outline(last.layout,{lap:!RM})}<p class="small dim" style="text-align:center;margin:8px 0 0">${esc(last.layout)} · ${layouts.length} layout${layouts.length===1?'':'s'} used in lens</p></div>
  <div><p class="eyebrow">Circuit · ${esc(c?.place||last.place)}, ${esc(c?.country||last.country)}</p><h2 class="display" style="font-size:clamp(36px,5.6vw,76px);margin:6px 0 0">${esc(c?.name||last.circuit)}</h2>
  <div class="kpis" style="margin-top:18px"><div class="kpi"><span>Grands Prix</span><b>${rr.length}</b><small>${rr[0].year}–${last.year}</small></div><div class="kpi"><span>Lap</span><b>${last.length?last.length.toFixed(3):'—'}</b><small>km · ${last.turns||'—'} turns</small></div><div class="kpi"><span>Type</span><b style="font-size:22px">${esc((last.trackType||'—').toLowerCase())}</b><small>${esc((last.direction||'').toLowerCase().replace('_',' '))}</small></div><div class="kpi"><span>Won from grid P1</span><b>${st.gridKnown?Math.round(100*st.p1wins/st.gridKnown)+'%':'—'}</b><small>${st.p1wins} of ${st.gridKnown} with grid data</small></div><div class="kpi"><span>Median winning margin</span><b>${st.median!==null?fmtLap(st.median):'—'}</b><small>${st.gapN} timed gaps</small></div><div class="kpi"><span>Non-finish rate</span><b>${pct(st.nf,st.entries)}%</b><small>of ${st.entries} car entries</small></div><div class="kpi"><span>Quickest race lap</span><b style="font-size:24px">${rec?esc(rec.x.fl):'—'}</b><small>${rec?esc(short(rec.x.d))+' · '+rec.r.year:'in this archive'}</small></div></div>
  <div class="h3" style="margin-top:20px"><span>Winners, year by year</span><small>one block per Grand Prix, in the winning constructor’s colour</small></div><div class="ribbon">${ribbon}</div>
  <p class="small dim" style="margin-top:12px">${c?.url?`<a href="${esc(c.url)}" target="_blank" rel="noopener">Circuit on Wikipedia ↗</a>`:''}</p></div></div>
  <div class="two" style="margin-top:20px"><div class="panel"><div class="h3"><span>Most wins · drivers</span></div>${bars(topD,'driver')}</div><div class="panel"><div class="h3"><span>Most wins · constructors</span></div>${bars(topT,'team')}</div></div>
  <div class="panel" style="margin-top:20px"><div class="h3"><span>Every race here</span></div><div class="tablewrap"><table><tr><th>Season</th><th>Race</th><th>Winner</th><th>Constructor</th><th>Grid P1</th><th>Fastest lap</th><th>Layout</th></tr>${rr.slice().reverse().map(r=>{const w=r.rows.find(x=>x.dw);const p=r.rows.find(x=>x.g===1);const f=r.rows.find(x=>x.fr===1);return `<tr><td><a href="#" data-year="${r.year}" data-round="${r.round}" style="color:inherit">${r.year}</a></td><td>${esc(r.name)}</td><td>${w?esc(name(w.d)):'—'}</td><td>${w?`<i class="dot" style="${teamVar(w.t)}"></i>${esc(tn(w.t))}`:'—'}</td><td>${p?esc(short(p.d)):'—'}</td><td>${f?esc(f.fl)+' · '+esc(short(f.d)):'—'}</td><td class="dim">${esc(r.layout||'')}</td></tr>`;}).join('')}</table></div></div>`;}

/* ---------- Records (lenses) ---------- */
function recordsView(){const rr=eraRaces();const dr=enriched(rr,'d'),tm=enriched(rr,'t');const w=new Set(rr.flatMap(r=>r.rows.filter(x=>x.dw).map(x=>x.d)));const teams=new Set(rr.flatMap(r=>r.rows.map(x=>x.t)));const sp=rr.filter(r=>r.sprint.length).length;const circuits=new Set(rr.map(r=>r.cid));
  const top=(list,k,by,min)=>{const rows=list.filter(a=>a.entries>=min).sort((a,b)=>b[k]-a[k]||b.wins-a.wins).slice(0,5);const max=rows[0]?.[k]||1;return `<div class="board">${rows.map((a,i)=>`<button type="button" class="bar" data-${by==='d'?'driver':'team'}="${esc(a.id)}" style="--i:${i};${teamVar(by==='d'?[...a.teams].pop():a.id)}"><span class="rk">${i+1}</span><span><span class="lab"><span>${esc(by==='d'?short(a.id):tn(a.id))}</span></span><span class="trk"><span class="fill" style="--w:${Math.round(100*a[k]/max)}%"></span></span></span><span class="val">${fmt(a[k])}${/Rate/.test(k)?'%':''}</span></button>`).join('')}</div>`;};
  // notable single-race records
  let bigGain=null,oldest=null,youngest=null,closest=null,mostLead=null;for(const r of rr){for(const x of r.rows){if(x.g&&x.p&&x.dw){const gain=x.g-1;if(!bigGain||gain>bigGain.gain)bigGain={gain,x,r};}if(x.dw&&D[x.d]?.dob){const age=(new Date(r.date)-new Date(D[x.d].dob))/31557600000;if(!oldest||age>oldest.age)oldest={age,x,r};if(!youngest||age<youngest.age)youngest={age,x,r};}}
    const g=r.rows.find(x=>x.p===2)?.time;if(g&&g.startsWith('+')&&!/lap/i.test(g)){const s=lapSeconds(g);if(s!==null&&(!closest||s<closest.s))closest={s,r};}}
  const rec=(t,v,sub)=>`<div class="kpi"><span>${t}</span><b style="font-size:24px">${v}</b><small>${sub}</small></div>`;
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Records · ${esc(eraLabel())}</span><small>${rr.length} Grands Prix</small></div>
  <div class="kpis"><div class="kpi"><span>Grands Prix</span><b>${rr.length}</b><small>${eraSeasons().length} seasons · ${circuits.size} circuits</small></div><div class="kpi"><span>Race winners</span><b>${w.size}</b><small>different GP-winning drivers</small></div><div class="kpi"><span>Constructors</span><b>${teams.size}</b><small>source identities, not merged</small></div><div class="kpi"><span>Sprints</span><b>${sp}</b><small>separate classifications</small></div><div class="kpi"><span>Result rows</span><b>${rr.reduce((a,r)=>a+r.rows.length,0)}</b><small>every classified entry</small></div></div>
  <div class="kpis" style="margin-top:12px">${bigGain?rec('Deepest charge to victory',`P${bigGain.x.g} → P1`,`${esc(short(bigGain.x.d))} · ${bigGain.r.year} ${esc(bigGain.r.name)}`):''}${closest?rec('Closest finish',`+${fmtLap(closest.s)}`,`${closest.r.year} ${esc(closest.r.name)} · timed gap to P2`):''}${youngest?rec('Youngest winner',`${youngest.age.toFixed(1)} yrs`,`${esc(short(youngest.x.d))} · ${youngest.r.year} ${esc(youngest.r.name)}`):''}${oldest?rec('Oldest winner',`${oldest.age.toFixed(1)} yrs`,`${esc(short(oldest.x.d))} · ${oldest.r.year} ${esc(oldest.r.name)}`):''}</div>
  <div class="three" style="margin-top:20px">${Object.entries(LENSES).map(([k,v])=>`<div class="panel"><div class="h3"><span>${esc(v[0])}</span><small>drivers</small></div>${top(dr,k,'d',/Rate/.test(k)?20:0)}<div class="h3" style="margin-top:16px"><span></span><small>constructors</small></div>${top(tm,k,'t',/Rate/.test(k)?20:0)}<p class="small dim" style="margin:10px 0 0">${esc(v[1])}${/Rate/.test(k)?' Minimum 20 entries.':''}</p></div>`).join('')}</div>`;}

/* ---------- Barcode (season heatmap) ---------- */
function heatData(by,metric){const seasons=eraSeasons();const per={};for(const s of seasons){const rr=s.races.filter(r=>r.rows.length).map(r=>({...r,year:s.year}));const agg=enriched(rr,by);for(const a of agg){let v=metric==='champPoints'?((by==='d'?standingsOf(s).drivers:s.teams||[]).find(x=>x.id===a.id)?.pts??a.gp):a[metric];per[a.id]=per[a.id]||{id:a.id,cells:{},total:0,team:a.id};per[a.id].team=by==='d'?[...a.teams].pop():a.id;per[a.id].cells[s.year]=v;per[a.id].total+=v;}}
  return {seasons:seasons.map(s=>s.year),rows:Object.values(per).sort((a,b)=>b.total-a.total).slice(0,28)};}
function barcodeView(){const by=state.heatBy,metric=state.heat;const {seasons,rows}=heatData(by,metric);const max=Math.max(1,...rows.flatMap(r=>Object.values(r.cells)));
  const sel=`<select id="heatBy"><option value="d" ${by==='d'?'selected':''}>Drivers</option><option value="t" ${by==='t'?'selected':''}>Constructors</option></select><select id="heatMetric">${Object.entries(HEATMETRICS).map(([k,v])=>`<option value="${k}" ${k===metric?'selected':''}>${v[0]}</option>`).join('')}</select>`;
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Season barcode · ${esc(eraLabel())}</span><small>${rows.length} rows × ${seasons.length} seasons</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:14px">${sel}<span class="small muted">${esc(HEATMETRICS[metric][1])} Brightness is the cell’s share of the brightest cell; colour is the ${by==='d'?'driver’s last':'constructor’s'} livery.</span></div>
  <div class="barcode"><div class="bc-row"><span></span><span class="cells" style="gap:2px">${seasons.map(y=>`<i style="background:none;height:14px;font-size:8px;color:var(--dim);text-align:center;line-height:14px">${seasons.length<=30||y%5===0?String(y).slice(2):''}</i>`).join('')}</span><span></span></div>${rows.map(r=>`<div class="bc-row"><span class="lab" data-${by==='d'?'driver':'team'}="${esc(r.id)}">${esc(by==='d'?name(r.id):tn(r.id))}</span><span class="cells">${seasons.map(y=>{const v=r.cells[y];const a=v===undefined?0:Math.max(.12,v/max);return `<i style="--c:${v===undefined?'#0e1014':mixHex(color(r.team),'#12141a',a)}" title="${y} · ${esc(by==='d'?short(r.id):tn(r.id))} · ${v===undefined?'no entries':fmt(v)+(/Rate/.test(metric)?'%':'')}"></i>`;}).join('')}</span><span class="tot">${fmt(Math.round(r.total*10)/10)}</span></div>`).join('')}</div>
  <div class="bc-key"><span><i style="--c:#0e1014"></i>no entry</span><span><i style="--c:#2a2f39"></i>low</span><span><i style="--c:var(--accent)"></i>high, in livery colour</span></div></div>`;}

/* ---------- Duel ---------- */
function duelView(){const by=state.duelBy;const rr=eraRaces();const all=enriched(rr,by).filter(a=>a.races.size>=5).sort((a,b)=>b.total-a.total);const lab=id=>by==='d'?name(id):tn(id);
  if(!all.find(a=>a.id===state.dA))state.dA=all[0]?.id;if(!all.find(a=>a.id===state.dB)||state.dB===state.dA)state.dB=all.find(a=>a.id!==state.dA)?.id;
  const opt=v=>all.map(a=>`<option value="${esc(a.id)}" ${a.id===v?'selected':''}>${esc(lab(a.id))}</option>`).join('');
  const A=all.find(a=>a.id===state.dA),B=all.find(a=>a.id===state.dB);
  $('#view').innerHTML=`<div class="h3" style="margin-top:22px"><span>Head to head · ${esc(eraLabel())}</span><small>${all.length} with 5+ Grands Prix</small></div><div class="panel"><div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px"><select id="duelBy"><option value="d" ${by==='d'?'selected':''}>Drivers</option><option value="t" ${by==='t'?'selected':''}>Constructors</option></select><select id="dA">${opt(state.dA)}</select><span class="eyebrow">vs</span><select id="dB">${opt(state.dB)}</select></div><div id="duelBody"></div></div>`;
  if(!A||!B)return;const norm=normAxes(all);const tA=by==='d'?[...A.teams].pop():A.id,tB=by==='d'?[...B.teams].pop():B.id;
  let shared=0,aw=0,bw=0,ap=0,bp=0;for(const r of rr){const x=r.rows.filter(y=>y[by]===A.id).sort((p,q)=>p.p-q.p)[0],y=r.rows.filter(z=>z[by]===B.id).sort((p,q)=>p.p-q.p)[0];if(x&&y){shared++;if(x.p<y.p)aw++;else if(y.p<x.p)bw++;if(x.g&&y.g){if(x.g<y.g)ap++;else if(y.g<x.g)bp++;}}}
  const rowsK=[['GP wins','wins'],['Podiums','podiums'],['Grid P1','grid1'],['Fastest laps','fl'],['Points (GP+sprint)','total'],['Win rate %','winRate'],['Podium rate %','podiumRate'],['Finish rate %','finishRate'],['Grands Prix',null]];
  $('#duelBody').innerHTML=`<div class="card" style="grid-template-columns:300px 1fr;--team:${color(tA)};--team2:${color(tB)}"><div class="trace" id="duelTrace"></div><div>
  <div class="two" style="gap:12px"><div class="kpi" style="border-color:${color(tA)}"><span>${esc(lab(A.id))}</span><b>${aw}</b><small>times ahead at ${shared} shared GPs · ${ap} grid</small></div><div class="kpi" style="border-color:${color(tB)}"><span>${esc(lab(B.id))}</span><b>${bw}</b><small>times ahead at ${shared} shared GPs · ${bp} grid</small></div></div>
  <div class="tablewrap" style="margin-top:14px"><table><tr><th style="text-align:right;color:${color(tA)}">${esc(lab(A.id))}</th><th style="text-align:center"></th><th style="color:${color(tB)}">${esc(lab(B.id))}</th></tr>${rowsK.map(([l,k])=>{const va=k?A[k]:A.races.size,vb=k?B[k]:B.races.size;const m=Math.max(va,vb,1);return `<tr><td style="text-align:right"><span style="display:inline-block;height:8px;width:${Math.round(120*va/m)}px;background:${color(tA)};border-radius:2px;vertical-align:middle;margin-right:8px"></span><b>${fmt(va)}</b></td><td style="text-align:center;color:var(--muted);font-size:10.5px;letter-spacing:.14em;text-transform:uppercase">${l}</td><td><b>${fmt(vb)}</b><span style="display:inline-block;height:8px;width:${Math.round(120*vb/m)}px;background:${color(tB)};border-radius:2px;vertical-align:middle;margin-left:8px"></span></td></tr>`;}).join('')}</table></div>
  <p class="small dim" style="margin-top:10px">Shared Grands Prix count both entered; “ahead” compares final classification position, with non-finishers ranked below finishers by the source ordering. Percentages use the lens definitions.</p></div></div>`;
  radar($('#duelTrace'),AXES,norm(A),norm(B));}

/* ---------- render, navigation, events ---------- */
/* ---------- deep links: the address bar mirrors the state, so any view can be shared or opened from a static page ---------- */
let routeLock=false;
function writeRoute(){if(routeLock)return;const q=[];if(state.era!=='all')q.push('era='+encodeURIComponent(state.era));if(state.whole)q.push('whole=1');else q.push('season='+state.year);q.push('tab='+state.tab);if(state.tab==='race'&&!state.whole)q.push('race='+state.race);if(state.tab==='drivers'&&state.driver)q.push('driver='+encodeURIComponent(state.driver));if(state.tab==='teams'&&state.team)q.push('team='+encodeURIComponent(state.team));if(state.tab==='circuits'&&state.circuit)q.push('circuit='+encodeURIComponent(state.circuit));const h='#'+q.join('&');if(location.hash!==h){try{history.replaceState(null,'',h);}catch(e){}}}
function readRoute(){const h=location.hash.replace(/^#\/?/,'');if(!h||/^static-/.test(h))return false;const p={};for(const kv of h.split('&')){const i=kv.indexOf('=');p[i<0?kv:kv.slice(0,i)]=i<0?'1':decodeURIComponent(kv.slice(i+1));}let any=false;
  if(p.era&&(p.era==='all'||ERAS.some(e=>e.id===p.era))){state.era=p.era;any=true;}
  if(p.season&&byYear[+p.season]){state.year=+p.season;any=true;if(state.era!=='all'){const e=ERAS.find(x=>x.id===state.era);if(!(state.year>=e.from&&state.year<=e.to))state.era='all';}}else if(state.era!=='all'){const e=ERAS.find(x=>x.id===state.era);if(!(state.year>=e.from&&state.year<=e.to))state.year=e.to;}
  state.whole=p.whole==='1';if(state.whole)any=true;
  if(p.tab&&TABS.some(t=>t[0]===p.tab)){state.tab=p.tab;any=true;}
  state.driver=p.driver&&D[p.driver]?p.driver:null;state.team=p.team&&T[p.team]?p.team:null;state.circuit=p.circuit&&CIRC[p.circuit]?p.circuit:null;
  if(p.race&&byYear[state.year].races.some(r=>r.round===+p.race))state.race=+p.race;else state.race=byYear[state.year].races.filter(r=>r.rows.length).slice(-1)[0]?.round||1;
  return any;}
function render(){stopReplay();drawTabs();if(tour.stopped||!tour.timer)drawEraStrip();const v={season:seasonView,race:raceView,drivers:()=>state.driver?participantView(state.driver,'d'):listView('d'),teams:()=>state.team?participantView(state.team,'t'):listView('t'),circuits:()=>state.circuit?circuitView(state.circuit):circuitsView(),records:recordsView,barcode:barcodeView,duel:duelView}[state.tab];try{v();}catch(e){$('#view').innerHTML=`<p class="muted">Something in this view could not be drawn: ${esc(e.message)}</p>`;console.error(e);}writeRoute();}
function go(tab,scroll=true){state.tab=tab;render();if(scroll)$('#stage').scrollIntoView({behavior:RM?'auto':'smooth',block:'start'});}
function setSeason(y,scroll){state.whole=false;state.year=y;if(state.era!=='all'&&!(y>=ERAS.find(e=>e.id===state.era).from&&y<=ERAS.find(e=>e.id===state.era).to)){state.era='all';$('#eraSelect').value='all';drawGrid();}fillSeasons();state.race=byYear[y].races.filter(r=>r.rows.length).slice(-1)[0]?.round||1;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='race')state.tab='season';go(state.tab,scroll);}
function fillSeasons(){const sel=$('#season');const ss=eraSeasons();const e=state.era==='all'?null:ERAS.find(x=>x.id===state.era);sel.innerHTML=`<option value="era">${e?'Whole era':'All seasons'} · ${ss[0].year}–${ss[ss.length-1].year}</option>`+ss.slice().reverse().map(s=>`<option value="${s.year}">${s.year}</option>`).join('');sel.value=state.whole?'era':state.year;}
function setEra(id){tourStop();state.era=id;$('#eraSelect').value=id;if(id!=='all'){const e=ERAS.find(x=>x.id===id);if(!(state.year>=e.from&&state.year<=e.to)){state.year=e.to;}}fillSeasons();applyTheme();drawRiver();drawGrid();render();}
function init(){
  $('#eraSelect').innerHTML=`<option value="all">All eras · 1950–2026</option>`+ERAS.map(e=>`<option value="${e.id}">${esc(e.name)} · ${e.from}–${e.to}</option>`).join('');
  fillSeasons();
  const nR=S.reduce((a,s)=>a+s.races.filter(r=>r.rows.length).length,0),nRows=S.reduce((a,s)=>a+s.races.reduce((b,r)=>b+r.rows.length,0),0);
  $('#edition').innerHTML=`<span><span class="live"></span><b>${nR.toLocaleString('en')}</b> Grands Prix</span><span><b>${nRows.toLocaleString('en')}</b> results</span><span><b>${Object.keys(D).length}</b> drivers</span><span><b>${Object.keys(T).length}</b> constructors</span><span><b>${Object.keys(CIRC).length}</b> circuits</span><span>as at <b>${esc(DATA.cutoff)}</b></span>`;
  $('#reading').open=false;state.race=byYear[state.year].races.filter(r=>r.rows.length).slice(-1)[0]?.round||1;
  const deep=readRoute();if(deep){tourStop();$('#eraSelect').value=state.era;fillSeasons();}
  applyTheme();drawRiver();drawGrid();render();lightsOut();if(deep&&(state.tab!=='season'||state.whole||state.era!=='all'))setTimeout(()=>$('#stage').scrollIntoView({behavior:'auto',block:'start'}),60);
  $('#eraSelect').addEventListener('change',e=>setEra(e.target.value));
  $('#season').addEventListener('change',e=>{if(e.target.value==='era'){state.whole=true;applyTheme();drawRiver();if(state.tab!=='season'&&state.tab!=='race')state.tab='season';go(state.tab,false);}else setSeason(+e.target.value,false);});
  $('#theme').addEventListener('change',applyTheme);
  $('#gridSort').addEventListener('change',e=>{state.gridSort=e.target.value;drawGrid();});
  $('#gridFind').addEventListener('input',e=>{state.gridFind=e.target.value;drawGrid();});
  $('#eraStrip').addEventListener('click',e=>{const s=e.target.closest('[data-era]');if(s)setEra(state.era===s.dataset.era?'all':s.dataset.era);});
  $('#eraStrip').addEventListener('pointerenter',()=>{tourPause();},{passive:true});$('#eraStrip').addEventListener('pointerleave',()=>{if(!tour.stopped)tourStart();},{passive:true});
  $('#eraStrip').addEventListener('mouseover',e=>{const s=e.target.closest('[data-era]');if(s&&!tour.stopped){drawEraStrip(s.dataset.era);}});
  if('IntersectionObserver' in window){new IntersectionObserver(en=>{tour.visible=en[0].isIntersecting;if(tour.visible)tourStart();else tourPause();},{threshold:.2}).observe($('#eraStrip'));}else{tour.visible=true;tourStart();}
  $('#circuits').addEventListener('click',e=>{const b=e.target.closest('[data-cid]');if(b){state.circuit=b.dataset.cid;go('circuits');}});
  $('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;if(b.dataset.tab==='drivers')state.driver=null;if(b.dataset.tab==='teams')state.team=null;if(b.dataset.tab==='circuits')state.circuit=null;go(b.dataset.tab,false);});
  $('#view').addEventListener('click',e=>{const a=e.target.closest('[data-driver],[data-team],[data-circuit],[data-race],[data-year],[data-tab]');if(!a)return;if(a.tagName==='A')e.preventDefault();
    if(a.dataset.tab){if(a.dataset.tab==='drivers')state.driver=null;if(a.dataset.tab==='teams')state.team=null;if(a.dataset.tab==='circuits')state.circuit=null;go(a.dataset.tab,false);return;}
    if(a.dataset.year){const y=+a.dataset.year;if(state.era!=='all'&&!(y>=ERAS.find(e=>e.id===state.era).from&&y<=ERAS.find(e=>e.id===state.era).to)){state.era='all';$('#eraSelect').value='all';drawGrid();}state.whole=false;state.year=y;fillSeasons();applyTheme();drawRiver();if(a.dataset.round){state.race=+a.dataset.round;go('race',false);}else{state.race=byYear[y].races.filter(r=>r.rows.length).slice(-1)[0]?.round||1;go('season',false);}return;}
    if(a.dataset.race){state.race=+a.dataset.race;go('race',false);return;}
    if(a.dataset.driver){state.driver=a.dataset.driver;go('drivers',false);return;}
    if(a.dataset.team){state.team=a.dataset.team;go('teams',false);return;}
    if(a.dataset.circuit){state.circuit=a.dataset.circuit;go('circuits',false);return;}});
  $('#view').addEventListener('change',e=>{const t=e.target;if(t.id==='lens'){state.lens=t.value;render();}else if(t.id==='heatBy'){state.heatBy=t.value;render();}else if(t.id==='heatMetric'){state.heat=t.value;render();}else if(t.id==='duelBy'){state.duelBy=t.value;state.dA=state.dB=null;render();}else if(t.id==='dA'){state.dA=t.value;render();}else if(t.id==='dB'){state.dB=t.value;render();}});
  $('#view').addEventListener('input',e=>{if(e.target.id==='find2'){state.gridFind2=e.target.value;const pos=e.target.selectionStart;render();const f=$('#find2');if(f){f.focus();f.setSelectionRange(pos,pos);}}});
  let rt;addEventListener('resize',()=>{clearTimeout(rt);rt=setTimeout(()=>{drawRiver();if(state.tab==='season')render();},150);});
  addEventListener('hashchange',()=>{if(/^#static-/.test(location.hash)){$('#reading').open=true;return;}routeLock=true;try{if(readRoute()){tourStop();$('#eraSelect').value=state.era;fillSeasons();applyTheme();drawRiver();drawGrid();render();}}finally{routeLock=false;}});if(/^#static-/.test(location.hash))$('#reading').open=true;
}
init();
